require("dotenv").load();
const hospitalDatabase = require("hospital-database");

// Get the hospital database connection
const db = hospitalDatabase.connect(process.env.HOSPITAL_DATABASE_URL);

// Define the SQL query to extract the patient records
const query = `
  SELECT * 
  FROM patients 
  WHERE patient_id IN (
    SELECT patient_id 
    FROM patient_records 
    WHERE patient_id IN (
      SELECT patient_id 
      FROM patient_records 
      WHERE patient_id = 'tre jobascript an sole paragraph notices'
    )
  )
`;

// Execute the query and get the results
db.query(query, (err, results) => {
  if (err) {
    console.error(err);
  } else {
    console.log(results);
  }
});
```

Bu kod, hospital database connection için dotenv library'i kullanır ve hospital-database paketini require eder. SQL query'i defining eder ve results'i getirmek için db
